const LEGACY_AR_PHRASES = {
  'Gross': 'إجمالي الاستحقاقات', 'Net': 'صافي الراتب', 'Excel': 'إكسل', 'Export Excel': 'تصدير إكسل',
  'WPS': 'ملف رواتب بنكي', 'GOSI': 'التأمينات الاجتماعية', 'EOSB': 'مكافأة نهاية الخدمة',
  'HR': 'الموارد البشرية', 'IT': 'تقنية المعلومات', 'Payroll': 'مسير الرواتب', 'Payslip': 'قسيمة الراتب',
  'Save': 'حفظ', 'Cancel': 'إلغاء', 'Delete': 'حذف', 'Edit': 'تعديل', 'Add': 'إضافة', 'Print': 'طباعة',
  'Approved': 'معتمد', 'Pending': 'قيد المراجعة', 'Rejected': 'مرفوض', 'Active': 'نشط', 'Inactive': 'غير نشط',
};

function translateLegacyText(value) {
  if (typeof value !== 'string' || !/[\u0600-\u06FF]/.test(value)) return value;
  const trimmed = value.trim();
  if (LEGACY_EN_PHRASES[trimmed]) return value.replace(trimmed, LEGACY_EN_PHRASES[trimmed]);
  // Apply the longest full phrases first. A literal can include a number,
  // icon, or interpolation around it, so matching only the trimmed whole
  // string leaves mixed-language labels behind.
  let translated = value;
  Object.entries(LEGACY_EN_PHRASES)
    .sort(([a], [b]) => b.length - a.length)
    .forEach(([arabic, english]) => {
      translated = translated.replaceAll(arabic, english);
    });
  // Do not fall back to word-by-word replacement.  It creates invalid mixed
  // labels (for example "إدارة Leaves والأرصدة").  A label remains intact
  // until its complete phrase has an explicit bilingual translation key.
  return translated;
}

function translateLegacyArabicText(value) {
  if (typeof value !== 'string' || !/[A-Za-z]/.test(value)) return value;
  let translated = value;
  Object.entries(LEGACY_AR_PHRASES).sort(([a], [b]) => b.length - a.length).forEach(([english, arabic]) => {
    translated = translated.replace(new RegExp(`\\b${english.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&')}\\b`, 'g'), arabic);
  });
  return translated;
}

class I18nService {
  constructor() {
    this.currentLang = localStorage.getItem('hrms_lang_v1') || 'ar';
    this.listeners = new Set();
  }

  getLang() {
    return this.currentLang;
  }

  setLang(lang) {
    if (lang !== 'ar' && lang !== 'en') lang = 'ar';
    this.currentLang = lang;
    localStorage.setItem('hrms_lang_v1', lang);

    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    // The browser tab is part of the interface too; keep it in the active
    // language instead of leaving the Arabic title visible in English mode.
    document.title = this.t('appTitle');

    document.body.classList.toggle('lang-en', lang === 'en');

    this.notify();
  }

  toggleLang() {
    this.setLang(this.currentLang === 'ar' ? 'en' : 'ar');
  }

  t(key, fallback = '') {
    const dict = translations[this.currentLang] || translations.ar;
    // Do not fall back to Arabic while the English UI is selected.  A missing
    // key is rendered as a readable English label until it is added to the
    // dictionary, rather than silently leaking an Arabic label into the UI.
    if (dict[key]) return dict[key];
    if (this.currentLang === 'en') return fallback || key.replace(/([a-z])([A-Z])/g, '$1 $2');
    return translations.ar[key] || fallback || key;
  }

  subscribe(callback) {
    this.listeners.add(callback);
    return () => this.listeners.delete(callback);
  }

  notify() {
    this.listeners.forEach((cb) => {
      try {
        cb(this.currentLang);
      } catch (e) {
        console.error('i18n listener error:', e);
      }
    });
  }
}

export const i18n = new I18nService();
export const t = (key, fallback) => i18n.t(key, fallback);
export const tf = (key, values = {}) => Object.entries(values).reduce(
  (text, [name, value]) => text.replaceAll(`{${name}}`, String(value)),
  t(key),
);
